def min_risk_classifier(p_w, loss_matrix, likelihoods):
    risks = []
    for i in range(len(loss_matrix)):
        # Expected risk for action i
        risk = sum(loss_matrix[i][j] * likelihoods[j] * p_w[j] for j in range(len(p_w)))
        risks.append(risk)
    return np.argmin(risks)

