# Simulated Branch and Bound search demonstration (Python 3.13+)
def evaluate_subset(subset):
    # Mock monotonic objective function (e.g., larger subset gives score)
    return len(subset) * 10 - (5 if 3 in subset else 0)

class BranchAndBoundSelector:
    def __init__(self, total_features, target_size):
        self.total_features = total_features
        self.target_size = target_size
        self.best_score = -float('inf')
        self.best_subset = None

    def search(self, current_index, current_subset):
        if len(current_subset) == self.target_size:
            score = evaluate_subset(current_subset)
            if score > self.best_score:
                self.best_score = score
                self.best_subset = list(current_subset)
                print(f'New best subset: {self.best_subset}, Score: {self.best_score}')
            return

        for i in range(current_index, self.total_features):
            # Pruning condition check (monotonicity bound)
            if len(current_subset) + (self.total_features - i) < self.target_size:
                continue
            self.search(i + 1, current_subset + [i])

# Run search across 5 features for target subset size 3
solver = BranchAndBoundSelector(total_features=5, target_size=3)
solver.search(0, [])
print('Optimal Feature Subset:', solver.best_subset)

