def verify_cauchy_schwarz(X, Y):
    # X, Y are matrices of shape (n_samples, n_features)
    inner_prods = np.abs(np.sum(X * Y, axis=1))
    norms_x = np.linalg.norm(X, axis=1)
    norms_y = np.linalg.norm(Y, axis=1)
    return np.all(inner_prods <= (norms_x * norms_y) + 1e-7)

