import numpy as np
# Train a simple linear classifier on synthetic data and test on real test data
def evaluate_synthetic(X_synth, y_synth, X_test, y_test):
    weights = np.linalg.pinv(X_synth.T @ X_synth) @ X_synth.T @ y_synth
    preds = np.round(X_test @ weights)
    return np.mean(preds == y_test)

import numpy as np
def get_cluster_representatives(X, cluster_labels):
# Select feature with highest variance in each cluster
    reps = []
    for c in np.unique(cluster_labels):
        cluster_feats = X[:, cluster_labels == c]
        variances = np.var(cluster_feats, axis=0)
        best_idx = np.argmax(variances)
        reps.append(cluster_feats[:, best_idx])
    return np.column_stack(reps)

